function widgetProxTarefas(){const hj=isoData(new Date());const a=A();const TT=a?a.turmas:[];
  const P=tarefas().filter(x=>!x.feito).sort((x,y)=>((x.prazo||'9999')).localeCompare(y.prazo||'9999')||((y.prio==='alta')-(x.prio==='alta'))||(x.criada-y.criada));
  const R_=a?reunioes(a).flatMap(r=>(r.decisoes||[]).map((d,i)=>({d,r,i}))).filter(o=>!o.d.ok&&o.d.prazo):[];
  const L=[...P.map(x=>({tipo:'t',x,prazo:x.prazo||''})),...R_.map(o=>({tipo:'r',o,prazo:o.d.prazo}))].sort((p,q)=>(p.prazo||'9999').localeCompare(q.prazo||'9999')).slice(0,6);
  const atr=P.filter(x=>x.prazo&&x.prazo<hj).length;const tN=id=>{const t=TT.find(z=>z.id===id);return t?t.nome:''};
  const quando=d=>!d?'sem prazo':d<hj?'atrasada · '+contagem(d):d===hj?'hoje':contagem(d);
  return `<div class="card wprox"><div class="row" style="margin-bottom:8px"><h2 style="margin:0">${ic('checks',18)} Próximas Tarefas</h2><span class="sp1"></span>${atr?`<span class="tag bad">${atr} em atraso</span>`:''}<span class="mut" style="font-size:12.5px">${P.length} por fazer</span><button class="btn sm" data-go="tarefas">Ver Todas</button></div>
   <div class="tdnew"><input id="wp-t" placeholder="Nova tarefa… (Enter)"><input type="date" id="wp-p" title="Prazo"><button class="btn sm pri" id="wp-ok" aria-label="Juntar">${ic('plus',14)}</button></div>
   ${L.length?`<div class="tdl">${L.map(e=>e.tipo==='t'?`<div class="tdi ${e.prazo&&e.prazo<hj?'atr':''}"><input type="checkbox" data-wpk="${e.x.id}" aria-label="Feita"><span class="tdt">${e.x.prio==='alta'?`<span class="tag bad" style="margin-right:6px">Alta</span>`:''}${esc(e.x.t)}<span class="mut"> · ${esc(quando(e.prazo))}${e.x.turma&&tN(e.x.turma)?' · '+esc(tN(e.x.turma)):''}</span></span></div>`
     :`<div class="tdi reun ${e.prazo<hj?'atr':''}"><span class="tdr">${ic('meet',13)}</span><span class="tdt">${esc(e.o.d.t)}<span class="mut"> · ${esc(quando(e.prazo))} · ${esc(reunTitulo(e.o.r,a))}</span></span></div>`).join('')}</div>`:'<p class="mut" style="margin:6px 0 0">Nada por fazer. 🎉</p>'}</div>`}
function bindProxTarefas(){const add=()=>{const t=$('#wp-t');if(!t||!t.value.trim())return;tarefas().push({id:uid(),t:t.value.trim(),prazo:$('#wp-p').value||'',prio:'normal',feito:false,criada:Date.now()});save();audit('Tarefas','Tarefa criada',t.value.trim());go('inicio');setTimeout(()=>$('#wp-t')&&$('#wp-t').focus(),60)};
  const ok=$('#wp-ok');if(ok){ok.onclick=add;$('#wp-t').onkeydown=e=>{if(e.key==='Enter')add()};$('#wp-p').onkeydown=e=>{if(e.key==='Enter')add()}}
  $$('[data-wpk]').forEach(c=>c.onchange=()=>{const x=tarefas().find(z=>z.id===c.dataset.wpk);if(!x)return;x.feito=c.checked;x.feitaEm=Date.now();save();c.closest('.tdi').classList.add('ok');try{tarBadge()}catch(_){}setTimeout(()=>{if(VIEW==='inicio')go('inicio')},350)})}
function posInicio(){const main=$('.in-main');if(!main)return;const side=$('.in-side');
  main.insertAdjacentHTML('afterbegin',widgetProxTarefas());{const il=$('.inlay');if(il)il.insertAdjacentHTML('beforeend','<div class="in-fav">'+widgetFavoritos()+'<div id="w-aulas">'+widgetAulasTurmas()+'</div></div>');bindAulasTurmas()}
  const tag=(el,k)=>{if(el&&!el.dataset.w)el.dataset.w=k};
  tag($('.wfav'),'favoritos');tag($('.wprox'),'tarefas');
  $$('.inlay .card').forEach(c=>{if(c.dataset.w)return;const h=(c.querySelector('h2')||{}).textContent||'';
    if(c.classList.contains('cdown'))tag(c,'contagem');else if(c.classList.contains('mzc'))tag(c,'matrizes');else if(c.classList.contains('dimps')||/Datas Importantes/.test(h))tag(c,'datas');
    else if(/Próximos Testes/.test(h))tag(c,'testes');else if(/^\s*Ano letivo/.test(h)&&c.querySelector('.tcards,.gof,.tcard'))tag(c,'turmas');else if(c.classList.contains('rcard')||/Reuni/.test(h)&&c.closest('.in-side'))tag(c,'reunioes');
    else if(c.classList.contains('anivc')||/Aniversário/.test(h))tag(c,'aniversarios');else if(/^\s*Hoje/.test(h))tag(c,'hoje')});
  const cf=cfgInicio();$$('.inlay [data-w]').forEach(c=>{const k=c.dataset.w;c.style.order=String(k==='tarefas'&&cf.ordem.indexOf(k)===0?-1:cf.ordem.indexOf(k)+1);if(!widgetOn(k))c.style.display='none'});
  const hero=$('.in-hero .esc-hero');if(hero&&!$('#in-pers')){const b=document.createElement('button');b.className='btn sm';b.id='in-pers';b.innerHTML=ic('sliders',14)+' Personalizar';b.title='Escolher e ordenar os cartões do Início';const g=hero.querySelector('[data-go="escola"]');hero.insertBefore(b,g||null)}
  {const hero2=$('.in-hero .esc-hero');if(hero2&&!$('#in-av')){let n=0;try{n=avisosUrgentes().length}catch(_){}const b=document.createElement('button');b.className='btn sm'+(n?' avon':'');b.id='in-av';b.innerHTML=ic('bell',14)+' Ver Avisos'+(n?` <span class="nbadge avn">${n}</span>`:'');b.title=n?n+' aviso(s) urgente(s) por tratar':'Sem avisos urgentes';const ref=$('#in-pers')||hero2.querySelector('[data-go="escola"]');hero2.insertBefore(b,ref||null);b.onclick=()=>mostrarAvisos(true)}}
  bindWidgets();bindProxTarefas();$$('.wprox [data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))}
